import org.junit.jupiter.params.provider.EnumSource;

class LmdbCacheSelectionTest {

	@ParameterizedTest
	@EnumSource(LmdbCacheImplementation.class)
	void dictionaryLookupsSurviveMutationRollbackReopenAndClear(LmdbCacheImplementation implementation,
			@TempDir File directory) throws Exception {
		LmdbStoreConfig config = config(implementation);
		File valuesDirectory = new File(directory, "values");
		List<Value> values = new ArrayList<>();
		for (int i = 0; i < 8; i++) {
			values.add(Values.iri("http://cache.example/ns-" + i + "/value"));
		}
		values.add(Values.bnode("cache-node"));
		values.add(Values.literal("non-inline literal ".repeat(5), Values.iri("urn:cache:datatype")));
		values.add(nested(Values.literal("nested literal")));
		Value[] batch = values.toArray(Value[]::new);
		long[] ids = new long[batch.length];
		Value aborted = Values.iri("http://aborted.example/namespace/value");
		ValueStore store = new ValueStore(valuesDirectory, config);
		try {
			store.startTransaction(true);
			store.setReplayDecision(new TxnReplayPolicy.Decision(new TxnReplayPolicy(), true, false, 0, 0, 0)
					.forNativeCheckpoints());
			store.storeValues(batch, ids, batch.length);
			assertValues(store, batch, ids);
			store.commit();
			assertValues(store, batch, ids);

			store.startTransaction(true);
			LmdbIRI first = store.createIRI("http://mutable.example/Aa");
			LmdbIRI equal = store.createIRI("http://mutable.example/Aa");
			long[] duplicateIds = new long[2];
			store.storeValues(new Value[] { first, equal }, duplicateIds, 2);
			assertEquals(duplicateIds[0], duplicateIds[1]);
			int originalHash = first.hashCode();
			first.setNamespaceAndIri("http://mutable.example/", "BB");
			assertEquals(originalHash, first.hashCode(), "The mutated key must still search its original cache set");
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(first));
			long replacementId = store.storeValue(first);
			assertNotEquals(duplicateIds[0], replacementId);
			assertEquals(duplicateIds[0], store.getId(equal),
					"An equal retained key must not authorize the mutated value");
			assertEquals(Values.iri("http://mutable.example/Aa"), store.getValue(duplicateIds[0]));
			assertEquals(Values.iri("http://mutable.example/BB"), store.getValue(replacementId));

			LmdbIRI datatype = store.createIRI("http://datatype.example/Aa");
			Value original = nested(store, store.createLiteral("nested mutable datatype ".repeat(5), datatype));
			Value equalNested = nested(store, store.createLiteral("nested mutable datatype ".repeat(5),
					store.createIRI("http://datatype.example/Aa")));
			store.storeValues(new Value[] { original, equalNested }, duplicateIds, 2);
			assertEquals(duplicateIds[0], duplicateIds[1]);
			datatype.setNamespaceAndIri("http://datatype.example/", "BB");
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(original));
			long[] mutatedIds = new long[1];
			store.storeValues(new Value[] { original }, mutatedIds, 1);
			assertNotEquals(duplicateIds[0], mutatedIds[0]);
			assertEquals(duplicateIds[0], store.getId(equalNested));
			assertEquals(nested(Values.literal("nested mutable datatype ".repeat(5),
					Values.iri("http://datatype.example/BB"))), store.getValue(mutatedIds[0]));
			store.commit();

			store.startTransaction(true);
			long abortedId = store.storeValue(aborted);
			assertEquals(aborted, store.getValue(abortedId));
			store.rollback();
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(aborted));
			assertValues(store, batch, ids);
		} finally {
			store.close();
		}

		ValueStore reopened = new ValueStore(valuesDirectory, config);
		try {
			assertValues(reopened, batch, ids);
			assertEquals(LmdbValue.UNKNOWN_ID, reopened.getId(aborted));
			reopened.clear();
			reopened.startTransaction(true);
			assertEquals(LmdbValue.UNKNOWN_ID, reopened.getId(batch[0]));
			Value replacement = Values.iri("http://replacement.example/namespace/value");
			long replacementId = reopened.storeValue(replacement);
			reopened.commit();
			assertEquals(replacement, reopened.getValue(replacementId));
			assertEquals(LmdbValue.UNKNOWN_ID, reopened.getId(batch[0]));
		} finally {
			reopened.close();
		}
	}

	@ParameterizedTest
	@EnumSource(LmdbCacheImplementation.class)
	void repositoryTransactionsUseSelectedCaches(LmdbCacheImplementation implementation, @TempDir File directory) {
		SailRepository repository = new SailRepository(new LmdbStore(directory, config(implementation)));
		try (RepositoryConnection connection = repository.getConnection()) {
			IRI predicate = Values.iri("urn:cache:predicate");
			for (IsolationLevels isolation : List.of(IsolationLevels.NONE, IsolationLevels.READ_COMMITTED)) {
				IRI subject = Values.iri("http://cache.example/" + isolation);
				connection.begin(isolation);
				connection.add(subject, predicate, Values.literal("stored " + isolation));
				connection.commit();
				assertTrue(connection.hasStatement(subject, predicate, Values.literal("stored " + isolation), false));
			}
			assertEquals(2, connection.size());
			connection.begin(IsolationLevels.READ_COMMITTED);
			connection.clear();
			connection.rollback();
			assertEquals(2, connection.size());
			assertTrue(connection.prepareBooleanQuery("ASK { ?s <urn:cache:predicate> ?o }").evaluate());
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config(LmdbCacheImplementation implementation) {
		return new LmdbStoreConfig().setCacheImplementation(implementation)
				.setValueIDCacheSize(5)
				.setNamespaceCacheSize(5)
				.setNamespaceIDCacheSize(5)
				.setValueCacheSize(1)
				.setInlineLiterals(false);
	}

	private static Value nested(Value literal) {
		return Values.tripleTerm(Values.bnode("outer"), Values.iri("urn:cache:outer"),
				Values.tripleTerm(Values.bnode("inner"), Values.iri("urn:cache:inner"), literal));
	}

	private static Value nested(ValueStore store, Value literal) {
		return store.createTripleTerm(store.createBNode("outer"), store.createIRI("urn:cache:outer"),
				store.createTripleTerm(store.createBNode("inner"), store.createIRI("urn:cache:inner"), literal));
	}

	private static void assertValues(ValueStore store, Value[] values, long[] ids) throws Exception {
		for (int i = 0; i < values.length; i++) {
			assertNotEquals(LmdbValue.UNKNOWN_ID, ids[i]);
			assertEquals(ids[i], store.getId(values[i]));
			assertEquals(values[i], store.getValue(ids[i]));
		}
	}
}
